[MAIN]
// ---- derived rate constants ------------------------------------------------
double MTTn   = MTT_N * MTTMULT;
double gam    = GAMMA_N * GAMMULT;
double ktrN   = 4.0 / MTTn;
double kcircN = log(2.0) / TAU_CIRC;
double ktrP   = 4.0 / MTT_P;
double kcircP = 1.0 / LIFE_P;          // mean-lifespan convention
double ktrE   = 4.0 / MTT_E;
double kcircE = 1.0 / LIFE_E;

// baseline compartment amounts, from the steady state of the transit chain
double PROL0  = ANC0 * kcircN / ktrN;
double MARG0  = ANC0 * MARG_RATIO;
double PROLP0 = PLT0 * kcircP / ktrP;
double PROLE0 = HB0  * kcircE / ktrE;
double RPOOL0 = PROL0 + ANC0 + MARG0;

// initial conditions
HSC_0   = RESERVE;
PROL_0  = PROL0;  TR1_0 = PROL0;  TR2_0 = PROL0;  TR3_0 = PROL0;
CIRC_0  = ANC0;   MARG_0 = MARG0;
PROLP_0 = PROLP0; TP1_0 = PROLP0; TP2_0 = PROLP0; TP3_0 = PROLP0;
PLT_0   = PLT0;
PROLE_0 = PROLE0; TE1_0 = PROLE0; TE2_0 = PROLE0; TE3_0 = PROLE0;
HB_0    = HB0;
TPO_0   = 1.0;    BAR_0 = 1.0;    FUNC_0 = 1.0;
TUMS_0  = TUM0 * (1.0 - RES_FRAC0);
TUMR_0  = TUM0 * RES_FRAC0;

// G-CSF product switch.  Filgrastim keeps a renal route and therefore an
// ANC-independent half-life; pegfilgrastim does not, so its half-life is a
// function of the neutrophil pool it has just created.
double gF, gKA, gV, gVP, gQ, gCLLIN, gVMAX, gKM;
if (GTYPE < 1.5) {                      // filgrastim
  gF = 0.65; gKA = 0.240; gV = 6.0; gVP = 4.5; gQ = 1.00;
  gCLLIN = 2.50; gVMAX = 12000.0; gKM = 25.0;
} else {                                // pegfilgrastim (or a long-acting peer)
  gF = G_F; gKA = G_KA; gV = G_V; gVP = G_VP; gQ = G_Q;
  gCLLIN = G_CLLIN; gVMAX = G_VMAX; gKM = G_KM;
}

[ODE]
// ===========================================================================
// 1. CYTOTOXIC PHARMACOKINETICS  (linear, one-way: nothing feeds back into it)
// ===========================================================================
double CA = A_C / A_V1;
double CB = B_C / B_V1;
double CC = C_C / C_V1;
double CD = D_C / D_V1;

dxdt_A_C  = -(A_CL/A_V1 + A_Q2/A_V1 + A_Q3/A_V1)*A_C
            + (A_Q2/A_V2)*A_P1 + (A_Q3/A_V3)*A_P2;
dxdt_A_P1 = (A_Q2/A_V1)*A_C - (A_Q2/A_V2)*A_P1;
dxdt_A_P2 = (A_Q3/A_V1)*A_C - (A_Q3/A_V3)*A_P2;
dxdt_B_C  = -(B_CL/B_V1 + B_Q2/B_V1)*B_C + (B_Q2/B_V2)*B_P1;
dxdt_B_P1 = (B_Q2/B_V1)*B_C - (B_Q2/B_V2)*B_P1;
dxdt_C_C  = -(C_CL/C_V1 + C_Q2/C_V1)*C_C + (C_Q2/C_V2)*C_P1;
dxdt_C_P1 = (C_Q2/C_V1)*C_C - (C_Q2/C_V2)*C_P1;
dxdt_D_C  = -(D_CL/D_V1 + D_Q2/D_V1)*D_C + (D_Q2/D_V2)*D_P1;
dxdt_D_P1 = (D_Q2/D_V1)*D_C - (D_Q2/D_V2)*D_P1;

dxdt_AUC_A = CA;  dxdt_AUC_B = CB;  dxdt_AUC_C = CC;  dxdt_AUC_D = CD;

// ---- effective driving concentration (threshold PD for paclitaxel) --------
// Paclitaxel's neutropenia tracks TIME ABOVE ~0.05 umol/L far better than it
// tracks AUC, which is the whole reason weekly 80 mg/m2 is less myelosuppressive
// than q3w 175 mg/m2 at a similar dose intensity.  Setting *_CTHR > 0 selects
// that form for the slot.
double EA = (A_CTHR > 0.0) ? ((CA > A_CTHR) ? CA - A_CTHR : 0.0) : CA;
double EB = (B_CTHR > 0.0) ? ((CB > B_CTHR) ? CB - B_CTHR : 0.0) : CB;
double EC = (C_CTHR > 0.0) ? ((CC > C_CTHR) ? CC - C_CTHR : 0.0) : CC;
double ED = (D_CTHR > 0.0) ? ((CD > D_CTHR) ? CD - D_CTHR : 0.0) : CD;

double sA = A_SLOPE * SENS * SENS_GLOBAL * SENS_TAXANE;   // slot A is taxane
double sB = B_SLOPE * SENS * SENS_GLOBAL;
double sC = C_SLOPE * SENS * SENS_GLOBAL;
double sD = D_SLOPE * SENS * SENS_GLOBAL;

double eA = sA * EA, eB = sB * EB, eC = sC * EC, eD = sD * ED;

double EdrugN = eA + eB + eC + eD;
double EcycW  = eA*A_FCYC + eB*B_FCYC + eC*C_FCYC + eD*D_FCYC;
double EdrugP = sA*A_SLOPEP*EA + sB*B_SLOPEP*EB + sC*C_SLOPEP*EC + sD*D_SLOPEP*ED;
double EdrugE = sA*A_SLOPEE*EA + sB*B_SLOPEE*EB + sC*C_SLOPEE*EC + sD*D_SLOPEE*ED;
double Edmuc  = eA*A_MUC + eB*B_MUC + eC*C_MUC + eD*D_MUC;
double Edhsc  = eA*A_HSC + eB*B_HSC + eC*C_HSC + eD*D_HSC;

// ===========================================================================
// 2. TRILACICLIB — G1 arrest of the CYCLING fraction of the HSPC pool
// ===========================================================================
double Ct = T_C / T_V1;
dxdt_T_C = -(T_CL + T_Q)/T_V1 * T_C + (T_Q/T_V2) * T_P;
dxdt_T_P = (T_Q/T_V1) * T_C - (T_Q/T_V2) * T_P;
dxdt_AUC_T = Ct;
double arrest = (Ct > 0.0) ? T_IMAX * Ct / (T_IC50 + Ct) : 0.0;
double Fcyc   = 1.0 - arrest;      // fraction still in cycle

// Only the CELL-CYCLE-DEPENDENT share of the kill can be protected by G1
// arrest.  This is why trilaciclib does much more for an S/G2M-specific
// topoisomerase poison than for a cycle-nonspecific platinum agent.
double fmix = (EdrugN > 1e-12) ? (EcycW / EdrugN) : 0.0;
double prot = (1.0 - fmix) + fmix * Fcyc;
double EdN  = EdrugN * prot;
double EdP  = EdrugP * prot;
double EdE  = EdrugE * prot;
double EdH  = Edhsc  * prot;

// ===========================================================================
// 3. G-CSF — PK with TARGET-MEDIATED clearance, and five PD actions
// ===========================================================================
double Cg = G_C / (gV * 1000.0);              // ng/mL
double RPOOL = TR3 + CIRC + MARG;             // receptor-bearing pool
double RP0   = (ANC0*kcircN/ktrN) + ANC0 + ANC0*MARG_RATIO;
// THE key term: the drug is eliminated by the very cells it creates, so its
// half-life falls as the ANC recovers.  For pegfilgrastim this is the ONLY
// clearance route, which is why one fixed 6 mg dose self-titrates and why the
// concentration collapses exactly when it is no longer needed.
double elim_tm = gVMAX * Cg / (gKM + Cg) * (RPOOL / RP0);

dxdt_G_DEP = -gKA * G_DEP;
dxdt_G_C   = gF*gKA*G_DEP - (gCLLIN/gV)*G_C - elim_tm
             - (gQ/gV)*G_C + (gQ/gVP)*G_P;
dxdt_G_P   = (gQ/gV)*G_C - (gQ/gVP)*G_P;
dxdt_G_E   = G_KEO * (Cg - G_E);
dxdt_AUC_G = Cg;
double Ce = (G_E > 0.0) ? G_E : 0.0;
double Eg = (Ce > 0.0) ? Ce / (G_EC50 + Ce) : 0.0;

// ===========================================================================
// 4. DEXAMETHASONE AND LEVOFLOXACIN
// ===========================================================================
double Cdex = DEX / DEX_V * 1000.0;           // mg/L -> ng/mL
dxdt_DEX = -(DEX_CL/DEX_V) * DEX;
double Edex = (Cdex > 0.0) ? Cdex / (DEX_EC50 + Cdex) : 0.0;
double Cabx = ABX / ABX_V;                    // mg/L
dxdt_ABX = -(ABX_CL/ABX_V) * ABX;
double Eabx = (Cabx > 0.0) ? ABX_IMAX * Cabx / (ABX_EC50 + Cabx) : 0.0;

// ===========================================================================
// 5. STEM POOL AND MARROW RESERVE
// ===========================================================================
double hsc = (HSC > 1e-9) ? HSC : 1e-9;
dxdt_HSC = KSELF * hsc * (1.0 - hsc/RESERVE) - KHSC_KILL * EdH * hsc;
dxdt_FIB = KFIB * EdH * (1.0 - FIB);
double reserve = hsc - FIB;
if (reserve < 0.0) reserve = 0.0;

// ===========================================================================
// 6. NEUTROPHIL LINEAGE — the delay line
// ===========================================================================
// G-CSF's transit acceleration is applied to BOTH the proliferation and the
// transit terms, because in this topology they are the SAME rate constant.
// Applying it only to the outflow makes accelerating transit empty the
// proliferative pool, which would have more G-CSF deepening the nadir.
double ktrNe = ktrN * (1.0 + EMAX_KTR * Eg);
double circ  = (CIRC > 0.05) ? CIRC : 0.05;
double fbN   = pow(ANC0 / circ, gam);
double ampN  = 1.0 + EMAX_AMP * Eg;
double PROL0b = ANC0 * kcircN / ktrN;

// The stem-derived influx is a FLUX set by upstream biology, so it is scaled by
// the BASE transit rate, not the accelerated one -- otherwise G-CSF would
// multiply the marrow's INPUT rather than shortening the pipeline.  With the
// base rate, faster transit shrinks the standing pool and leaves the flux
// through it unchanged: it moves the DELAY without moving the LEVEL, which is
// the separation the whole model is built around.
// NOTE the absence of `reserve` on the SELF-RENEWAL term.  Multiplying the
// self-renewal gain by the marrow reserve couples a small stem-cell loss to a
// huge change in the steady-state count through the 1/gamma exponent -- a 12%
// reserve loss HALVED the baseline ANC, which is not what a previously-treated
// patient looks like.  Reserve belongs on the stem-derived INFLUX, where a 12%
// loss costs 12% of the marrow's input.  The clinical consequence is the right
// one: reduced reserve barely moves the baseline count and markedly slows
// RECOVERY, because during the nadir the influx term is all that is left.
double prol_in = ktrNe*(1.0-PHI)*PROL*fbN*ampN*(1.0-EdN)
               + ktrN*PHI*PROL0b*hsc*fbN*ampN*(1.0-FIB)*(1.0-EdN);

// NOTE: (1 - EdN) is deliberately NOT clamped at zero.  At the published
// Friberg slopes EdN exceeds 1 during the infusion, so the term goes negative
// and the proliferative pool is actively DEPLETED rather than merely stopped.
// Clamping it caps the achievable nadir far above what is observed.
dxdt_PROL = prol_in - ktrNe*PROL;
dxdt_TR1  = ktrNe*(PROL - TR1);
dxdt_TR2  = ktrNe*(TR1  - TR2);
double krel = KREL_MAX * EMAX_REL * Eg;
dxdt_TR3  = ktrNe*TR2 - (ktrNe + krel)*TR3;

// Margination falls with corticosteroid (demargination) and, in this model, NOT
// with G-CSF.  Circulating clearance is slowed by G-CSF (anti-apoptotic).
double kmi = KMARG * (1.0 - DEX_DEMARG*Edex) * (1.0 - EMAX_DEMARG*Eg);
double kmo = KMARG;
double kcircNe = kcircN * (1.0 - EMAX_SURV*Eg);
double consume = KCONSUME * BACT/(B50 + BACT) * CIRC;

dxdt_CIRC = (ktrNe + krel)*TR3 - kcircNe*CIRC - kmi*CIRC + kmo*MARG - consume;
dxdt_MARG = kmi*CIRC - kmo*MARG;

// ===========================================================================
// 7. PLATELET AND ERYTHROID LINEAGES — same insult, different clocks
// ===========================================================================
double plt_ = (PLT > 2.0) ? PLT : 2.0;
double fbP  = pow(PLT0/plt_, GAMMA_P) * TPO;
if (fbP > FBP_MAX) fbP = FBP_MAX;
double PROLP0b = PLT0 * kcircP / ktrP;
dxdt_PROLP = ktrP*(1.0-PHI_PE)*PROLP*fbP*(1.0-EdP)
           + ktrP*PHI_PE*PROLP0b*hsc*fbP*(1.0-FIB)*(1.0-EdP) - ktrP*PROLP;
dxdt_TP1 = ktrP*(PROLP - TP1);
dxdt_TP2 = ktrP*(TP1 - TP2);
dxdt_TP3 = ktrP*(TP2 - TP3);
dxdt_PLT = ktrP*TP3 - kcircP*PLT;
// Thrombopoietin is cleared through c-Mpl on platelets: the same
// target-mediated trick as G-CSF, one lineage over.  The TPO_MAX ceiling is
// applied to the PRODUCTION branch only -- applied to both it becomes a sign
// trap, because above the ceiling both factors are negative and TPO then grows
// faster the further past its limit it goes.
double tpo_drive = 1.0 - TPO * PLT / PLT0;
if (tpo_drive > 0.0) tpo_drive *= (1.0 - TPO/TPO_MAX > 0.0 ? 1.0 - TPO/TPO_MAX : 0.0);
dxdt_TPO = 0.010 * tpo_drive;

double hb_ = (HB > 3.0) ? HB : 3.0;
double fbE = pow(HB0/hb_, GAMMA_E);
double PROLE0b = HB0 * kcircE / ktrE;
dxdt_PROLE = ktrE*(1.0-PHI_PE)*PROLE*fbE*(1.0-EdE)
           + ktrE*PHI_PE*PROLE0b*hsc*fbE*(1.0-FIB)*(1.0-EdE) - ktrE*PROLE;
dxdt_TE1 = ktrE*(PROLE - TE1);
dxdt_TE2 = ktrE*(TE1 - TE2);
dxdt_TE3 = ktrE*(TE2 - TE3);
dxdt_HB  = ktrE*TE3 - kcircE*HB;

// ===========================================================================
// 8. MUCOSAL BARRIER, NEUTROPHIL FUNCTION, INFECTION, FEVER
// ===========================================================================
dxdt_BAR = KHEAL_BAR*(1.0 - BAR) - KDAM_BAR*Edmuc*BAR;

// FUNCTION is a state distinct from COUNT.  Corticosteroid lowers it while
// raising the count; G-CSF raises both; the cytotoxic itself lowers it.
double edn1 = (EdrugN < 1.0) ? EdrugN : 1.0;
double fun_target = (1.0 - DEX_FUNC*Edex) * (1.0 + EMAX_FUN*Eg) * (1.0 - 0.25*edn1);
dxdt_FUNC = KFUNC * (fun_target - FUNC);

double breach = (BAR < 1.0) ? 1.0 - BAR : 0.0;
double influx = K_TRANS * breach * (1.0 - Eabx);
double func_  = (FUNC > 0.0) ? FUNC : 0.0;
double ANCeff = (CIRC + MARG) * func_;        // the defence that actually acts
double killB  = KKILL_B * ANCeff * BACT / (1.0 + BACT/B50);
dxdt_BACT = influx + KGROW_B*(1.0 - Eabx)*BACT*(1.0 - BACT/BMAX) - killB;

dxdt_IL6  = KIL6_B*BACT - KIL6_OUT*IL6;
dxdt_CRP  = KCRP_IN*IL6 - KCRP_OUT*CRP;
dxdt_TDEV = KT_IN*IL6 - KT_OUT*TDEV;

// ===========================================================================
// 9. COUNTERS — duration and hazard, not depth
// ===========================================================================
dxdt_DSN_H = (CIRC < 0.5) ? 1.0 : 0.0;
double depth = (CIRC < 0.5) ? (1.0 - CIRC/0.5) : 0.0;
dxdt_CUMHAZ = HFN_BASE
            + HFN_K * pow(depth, HFN_P) * (1.0 + HFN_BAR*breach) * (1.0 - 0.55*Eabx);

// ===========================================================================
// 10. TUMOUR — regrowth here; the log-kill is an event-driven impulse
// ===========================================================================
double kg = log(2.0)/TDOUBLE;
dxdt_TUMS = kg*TUMS;
dxdt_TUMR = kg*TUMR;

[TABLE]
double ANC       = CIRC;
double DSN_D     = DSN_H/24.0;
double P_FN      = 1.0 - exp(-CUMHAZ);
double TEMP      = 36.8 + TDEV;
double TUMOUR    = TUMS + TUMR;
double RESERVE_N = HSC - FIB;
double ANC_EFF   = (CIRC + MARG) * FUNC;
double GRADE     = (CIRC >= 2.0) ? 0.0 :
                   ((CIRC >= 1.5) ? 1.0 :
                   ((CIRC >= 1.0) ? 2.0 :
                   ((CIRC >= 0.5) ? 3.0 : 4.0)));
double CGCSF     = G_C / (G_V * 1000.0);
double CDOCE     = A_C / A_V1;
double FEBRILE   = ((CIRC < 0.5) && (36.8 + TDEV >= 38.3)) ? 1.0 : 0.0;
double GATE_D1   = ((CIRC >= 1.5) && (PLT >= 100.0)) ? 1.0 : 0.0;

[CAPTURE] @annotated
ANC       : 10^9/L, absolute neutrophil count (the measured number)
ANC_EFF   : 10^9/L, effective defence = (circulating + marginated) x function
GRADE     : -, CTCAE neutropenia grade
DSN_D     : d, cumulative days with ANC < 0.5
P_FN      : -, cumulative probability of febrile neutropenia
FEBRILE   : -, 1 when the FN definition is met at this instant
GATE_D1   : -, 1 when the day-1 CBC gate would allow the next cycle
TEMP      : degC, core temperature
TUMOUR    : au, total tumour burden
RESERVE_N : -, marrow reserve net of irreversible damage
CGCSF     : ng/mL, G-CSF plasma concentration
CDOCE     : umol/L, slot A cytotoxic concentration

